insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) select 201,null,'Folhas da Lua — combine e crie sua planta','Observe a evolução do mesmo desenho e adapte a construção à sua própria ideia.','[{"hex": "#237580", "label": "Azul-petróleo"}, {"hex": "#8766ad", "label": "Roxo"}, {"hex": "#ce9f49", "label": "Dourado"}]'::jsonb,'/tutorials/folhas-da-lua/passo-7.svg','Experimente tamanhos, cores e detalhes diferentes. O exemplo é uma inspiração, não a única resposta correta.',true where not exists(select 1 from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null);
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,1,'Seis formas de folhas','Compare o contorno à esquerda com a folha colorida à direita. Desenhe suas próprias seis opções.','/tutorials/folhas-da-lua/passo-1.svg','reference','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,2,'Escolha e combine duas','Combine a folha em lança com a folha em coração. Alterne seus tamanhos e posições no caule.','/tutorials/folhas-da-lua/passo-2.svg','construction','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,3,'Esboce sua planta','Faça o caule curvo e distribua as duas folhas escolhidas. Deixe espaço para pequenas flores.','/tutorials/folhas-da-lua/passo-3.svg','sketch','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,4,'Contornos e nervuras','Reforce o mesmo esboço. A nervura central e as ramificações acompanham o formato da folha.','/tutorials/folhas-da-lua/passo-4.svg','lineart','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,5,'Pinte com poucos tons','Folhas em coração recebem roxo; folhas em lança, azul-petróleo. As flores recebem dourado.','/tutorials/folhas-da-lua/passo-5.svg','color','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,6,'Detalhes ampliados','Veja as nervuras seguindo o crescimento da folha e uma faixa mais clara no lado iluminado.','/tutorials/folhas-da-lua/passo-6.svg','detail','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,7,'Resultado final — uma inspiração','Uma planta imaginária com as duas folhas, flores douradas e lua ao fundo. Mude a silhueta, as cores e os detalhes.','/tutorials/folhas-da-lua/passo-7.svg','final','' from public.visual_tutorials where challenge_id is not distinct from 201 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) select 1225,null,'Cesta de piquenique — primeiros traços','Observe a evolução do mesmo desenho e adapte a construção à sua própria ideia.','[{"hex": "#ce9f49", "label": "Palha e pão"}, {"hex": "#e5a18f", "label": "Frutas"}, {"hex": "#3d2b45", "label": "Contorno"}]'::jsonb,'/tutorials/cesta-iniciante/passo-6.svg','Experimente tamanhos, cores e detalhes diferentes. O exemplo é uma inspiração, não a única resposta correta.',true where not exists(select 1 from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null);
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,1,'Observe a cesta','A borda mostra a abertura; a alça acompanha a largura do cesto. Compare as curvas antes dos alimentos.','/tutorials/cesta-iniciante/passo-1.svg','reference','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,2,'Construa a mesma cesta','Defina borda oval, alça e laterais inclinadas. O fundo é mais estreito que a abertura.','/tutorials/cesta-iniciante/passo-2.svg','construction','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,3,'Acrescente pão e frutas','Encaixe o pão atrás da borda e as frutas no meio. As sobreposições mostram o que está mais perto.','/tutorials/cesta-iniciante/passo-3.svg','sketch','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,4,'Desenhe a trama','Linhas horizontais seguem a curva da cesta. As tiras verticais acompanham suas laterais.','/tutorials/cesta-iniciante/passo-4.svg','lineart','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,5,'Separe materiais e cores','Dourado no cesto, creme no pão e coral nas frutas. Preserve áreas claras para mostrar volume.','/tutorials/cesta-iniciante/passo-5.svg','color','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,6,'Resultado final — uma inspiração','A luz destaca a borda e a sombra prende a cesta à superfície. Mude os alimentos e a organização.','/tutorials/cesta-iniciante/passo-6.svg','final','' from public.visual_tutorials where challenge_id is not distinct from 1225 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
