insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) select 3006,null,'Cinco olhos — diferentes direções','Observe a evolução do mesmo desenho e adapte a construção à sua própria ideia.','[{"hex": "#237580", "label": "Íris"}, {"hex": "#e5a18f", "label": "Pálpebras"}, {"hex": "#3d2b45", "label": "Contorno"}]'::jsonb,'/tutorials/olhos-pratica/passo-5.svg','Experimente tamanhos, cores e detalhes diferentes. O exemplo é uma inspiração, não a única resposta correta.',true where not exists(select 1 from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null);
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,1,'Reconheça as pálpebras','O contorno superior é mais arqueado; a pálpebra inferior é mais suave.','/tutorials/olhos-pratica/passo-1.svg','reference','' from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,2,'Posicione íris e pupila','A íris entra sob a pálpebra superior. A pupila acompanha a direção do olhar.','/tutorials/olhos-pratica/passo-2.svg','construction','' from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,3,'Cílios e sobrancelha','Cílios saem das bordas das pálpebras. Use poucos traços e varie a direção.','/tutorials/olhos-pratica/passo-3.svg','lineart','' from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,4,'Luz e sombra no olho','Reserve um brilho na íris. A sombra abaixo do olho ajuda a mostrar seu volume.','/tutorials/olhos-pratica/passo-4.svg','color','' from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,5,'Resultado final — uma inspiração','Crie cinco olhos olhando em direções diferentes. Veja como íris e pupila mudam de posição.','/tutorials/olhos-pratica/passo-5.svg','final','' from public.visual_tutorials where challenge_id is not distinct from 3006 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) select 3012,null,'Cinco mãos abertas — observe e varie','Observe a evolução do mesmo desenho e adapte a construção à sua própria ideia.','[{"hex": "#ebc5b5", "label": "Pele"}, {"hex": "#e5a18f", "label": "Sombra"}, {"hex": "#3d2b45", "label": "Contorno"}]'::jsonb,'/tutorials/maos-pratica/passo-5.svg','Experimente tamanhos, cores e detalhes diferentes. O exemplo é uma inspiração, não a única resposta correta.',true where not exists(select 1 from public.visual_tutorials where challenge_id is not distinct from 3012 and lesson_id is not distinct from null);
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,1,'Observe a mão aberta','Compare os cinco dedos e o espaço do polegar. Os dedos têm comprimentos diferentes.','/tutorials/maos-pratica/passo-1.svg','reference','' from public.visual_tutorials where challenge_id is not distinct from 3012 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,2,'Organize palma e dedos','Veja o arco dos dedos e as linhas da palma. O polegar nasce ao lado da mão.','/tutorials/maos-pratica/passo-2.svg','construction','' from public.visual_tutorials where challenge_id is not distinct from 3012 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
