insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,4,'Dê volume à mesma mão','Use tom claro na frente e um tom mais escuro nas dobras. Varie a força do contorno.','/tutorials/maos-pratica/passo-4.svg','color','' from public.visual_tutorials where challenge_id is not distinct from 3012 and lesson_id is not distinct from null and revision=0 on conflict do nothing;
