insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,5,'Resultado final — uma inspiração','Uma inspiração do estudo finalizado. Observe os contornos e os detalhes; adapte a construção à sua referência.','/tutorials/olhos-aula/passo-5.svg','final','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'olhos-iniciante' and revision=0 on conflict do nothing;
insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) select null,'maos-iniciante','Uma mão aberta — palma, dedos e dobras','Observe a evolução do mesmo desenho e adapte a construção à sua própria ideia.','[{"hex": "#ebc5b5", "label": "Pele"}, {"hex": "#e5a18f", "label": "Sombra"}, {"hex": "#3d2b45", "label": "Contorno"}]'::jsonb,'/tutorials/maos-aula/passo-5.svg','Experimente tamanhos, cores e detalhes diferentes. O exemplo é uma inspiração, não a única resposta correta.',true where not exists(select 1 from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante');
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,1,'Observe a mão aberta','Compare os cinco dedos e o espaço do polegar. Os dedos têm comprimentos diferentes.','/tutorials/maos-aula/passo-1.svg','reference','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante' and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,2,'Organize palma e dedos','Veja o arco dos dedos e as linhas da palma. O polegar nasce ao lado da mão.','/tutorials/maos-aula/passo-2.svg','construction','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante' and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,3,'Marque as articulações','As dobras acompanham as articulações. Compare os segmentos sem apertar o lápis.','/tutorials/maos-aula/passo-3.svg','lineart','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante' and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,4,'Dê volume à mesma mão','Use tom claro na frente e um tom mais escuro nas dobras. Varie a força do contorno.','/tutorials/maos-aula/passo-4.svg','color','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante' and revision=0 on conflict do nothing;
insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select id,5,'Resultado final — uma inspiração','Uma inspiração do estudo finalizado. Observe os contornos e os detalhes; adapte a construção à sua referência.','/tutorials/maos-aula/passo-5.svg','final','' from public.visual_tutorials where challenge_id is not distinct from null and lesson_id is not distinct from 'maos-iniciante' and revision=0 on conflict do nothing;
